import{_ as e,o as t,c as r,a2 as n}from"./chunks/framework.CdvW4CUT.js";const u=JSON.parse('{"title":"How to Join LlamaCraft","description":"","frontmatter":{},"headers":[],"relativePath":"guide/how-to-join.md","filePath":"guide/how-to-join.md"}'),a={name:"guide/how-to-join.md"};function i(l,o,d,s,c,h){return t(),r("div",null,[...o[0]||(o[0]=[n('<h1 id="how-to-join-llamacraft" tabindex="-1">How to Join LlamaCraft <a class="header-anchor" href="#how-to-join-llamacraft" aria-label="Permalink to &quot;How to Join LlamaCraft&quot;">​</a></h1><p>LlamaCraft is a unified cross-play server running on PaperMC. Players on Java Edition, Bedrock Edition (iOS, Android, Windows, Consoles), and Education Edition can all play together in the same world.</p><hr><h2 id="server-address-details" tabindex="-1">Server Address Details <a class="header-anchor" href="#server-address-details" aria-label="Permalink to &quot;Server Address Details&quot;">​</a></h2><ul><li><strong>Server IP / Hostname</strong>: <code>164.152.106.210</code></li><li><strong>Java Port</strong>: <code>25565</code> (Default)</li><li><strong>Bedrock Port</strong>: <code>19132</code> (Default)</li></ul><hr><h2 id="_1-java-edition-pc-mac-linux" tabindex="-1">1. Java Edition (PC / Mac / Linux) <a class="header-anchor" href="#_1-java-edition-pc-mac-linux" aria-label="Permalink to &quot;1. Java Edition (PC / Mac / Linux)&quot;">​</a></h2><ol><li>Launch Minecraft Java Edition (Version <code>1.20.x</code> or <code>1.21.x</code>).</li><li>Click <strong>Multiplayer</strong> &gt; <strong>Add Server</strong>.</li><li>Set <strong>Server Name</strong> to <code>LlamaCraft</code>.</li><li>Enter <strong>Server Address</strong>: <code>164.152.106.210</code>.</li><li>Click <strong>Done</strong>, select the server, and click <strong>Join Server</strong>.</li></ol><hr><h2 id="_2-bedrock-mobile-windows-10-11" tabindex="-1">2. Bedrock Mobile &amp; Windows 10/11 <a class="header-anchor" href="#_2-bedrock-mobile-windows-10-11" aria-label="Permalink to &quot;2. Bedrock Mobile &amp; Windows 10/11&quot;">​</a></h2><ol><li>Open Minecraft on your phone, tablet, or Windows PC.</li><li>Tap <strong>Play</strong> &gt; navigate to the <strong>Servers</strong> tab.</li><li>Scroll to the bottom and click <strong>Add Server</strong>.</li><li>Fill in the fields: <ul><li><strong>Server Name</strong>: <code>LlamaCraft</code></li><li><strong>Server Address</strong>: <code>164.152.106.210</code></li><li><strong>Port</strong>: <code>19132</code></li></ul></li><li>Click <strong>Save</strong> or <strong>Play</strong> to connect immediately.</li></ol><hr><h2 id="_3-consoles-xbox-playstation-nintendo-switch" tabindex="-1">3. Consoles (Xbox, PlayStation, Nintendo Switch) <a class="header-anchor" href="#_3-consoles-xbox-playstation-nintendo-switch" aria-label="Permalink to &quot;3. Consoles (Xbox, PlayStation, Nintendo Switch)&quot;">​</a></h2><p>Because console platforms restrict custom external server IPs in their main menu, use one of the two standard connection bridges:</p><h3 id="method-a-bedrockconnect-dns-no-app-required" tabindex="-1">Method A: BedrockConnect DNS (No App Required) <a class="header-anchor" href="#method-a-bedrockconnect-dns-no-app-required" aria-label="Permalink to &quot;Method A: BedrockConnect DNS (No App Required)&quot;">​</a></h3><ol><li>Go to your console&#39;s <strong>Network Settings</strong> &gt; <strong>Advanced Settings</strong> &gt; <strong>DNS Settings</strong>.</li><li>Change DNS from Automatic to <strong>Manual</strong>.</li><li>Set <strong>Primary DNS</strong> to <code>104.238.130.180</code> (or <code>172.86.113.167</code>).</li><li>Set Secondary DNS to <code>1.1.1.1</code> (or <code>8.8.8.8</code>).</li><li>Open Minecraft, click <strong>Play</strong> &gt; <strong>Servers</strong>, and join any featured server (e.g., The Hive or CubeCraft).</li><li>A BedrockConnect menu will pop up. Select <strong>Connect to a Server</strong>, type <code>164.152.106.210</code> with port <code>19132</code>, and check <strong>Add to server list</strong>.</li></ol><h3 id="method-b-mc-server-connector-app-mobile-lan-bridge" tabindex="-1">Method B: MC Server Connector App (Mobile LAN Bridge) <a class="header-anchor" href="#method-b-mc-server-connector-app-mobile-lan-bridge" aria-label="Permalink to &quot;Method B: MC Server Connector App (Mobile LAN Bridge)&quot;">​</a></h3><ol><li>Download <strong>MC Server Connector</strong> or <strong>BedrockTogether</strong> on your phone (iOS / Android).</li><li>Connect your phone to the same Wi-Fi network as your console.</li><li>In the app, enter IP <code>164.152.106.210</code> and Port <code>19132</code>, then tap <strong>Play / Start</strong>.</li><li>On your console, open Minecraft, go to <strong>Friends</strong>, and click the LAN game that appears under <code>LlamaCraft</code>.</li></ol><hr><h2 id="_4-minecraft-education-edition" tabindex="-1">4. Minecraft Education Edition <a class="header-anchor" href="#_4-minecraft-education-edition" aria-label="Permalink to &quot;4. Minecraft Education Edition&quot;">​</a></h2><ol><li>Ensure your client supports external protocol connections.</li><li>Enter the server host <code>164.152.106.210</code> and port <code>19132</code>.</li><li>If connecting behind a school network, verify UDP port 19132 outbound traffic is open.</li></ol>',21)])])}const p=e(a,[["render",i]]);export{u as __pageData,p as default};
